section.sourcecode:
Descriptor = { 1 => AgentID, ; subject (accountable identity) 2 => uint, ; seq — strictly increasing per subject 3 => [+ Version], ; MAP versions spoken 4 => [+ uint], ; suites supported 5 => [+ tstr], ; multiaddrs / URLs per transport 6 => [+ CapEntry], ; capabilities offered ? 7 => [+ ModelEntry], ? 8 => HardwareClass, ? 9 => PricingHint, ? 10 => SecurityProfile, ? 11 => [+ MemoryTopic], ? 12 => [+ ZoneLabel], ; zones served (default [2]) ? 13 => uint, ; descriptor validity, ms (<= 24h) ? 14 => ExtMap }
CapEntry = { 1 => CapURI, ; from the ontology, §4 ? 2 => { * int => any } ; capability-specific parameters } ; (registered per ontology branch)
ModelEntry = { 1 => tstr, ; model name (informative) ? 2 => Multihash, ; weights digest — the verifiable id ? 3 => uint, ; max context tokens ? 4 => tstr, ; quantization label ? 5 => tstr ; runtime ("ollama","vllm","gateway") }
HardwareClass = { ; COARSE BUCKETS ONLY (arch §8.2) ? 1 => uint, ; vram-class: 0=n/a,1<=8,2=16,3=24, ; 4=32,5=48,6=64,7=96,8=128,9>128 GB ? 2 => uint, ; ram-class (same scale) ? 3 => uint, ; accel: 0 none,1 consumer-gpu, ; 2 datacenter-gpu,3 npu,4 cpu-only ? 4 => uint ; bandwidth-class: 1<=100Mb,2<=1Gb,3>1Gb }
PricingHint = { ; nonbinding; binding prices via ? 1 => tstr, ; PAY_QUOTE (pay §3) ? 2 => [ int, int ], ; per-1M-tokens [exp, mantissa] tag-4 ? 3 => [ int, int ], ; per-minute ? 4 => bool ; barter accepted }
SecurityProfile = { ? 1 => uint, ; sandbox: 0 none,1 container,2 microVM, ; 3 wasm,4 tee ? 2 => bool, ; remote attestation available ? 3 => [* tstr] ; tool allowlist (ontology tool URIs) }
MemoryTopic = { 1 => tstr, ; domain label 2 => tstr, ; embedding-model identifier (REQUIRED — 3 => uint, ; dimension similarity across ? 4 => uint, ; vector count models is undefined; ? 5 => Multihash ; index digest critique "0.85") }

StatusQuery  = { ? 1 => [+ CapURI], ? 2 => bstr .size 8 /*echo*/ }
StatusReport = {
  1 => Timestamp,
  ? 2 => uint,        ; queue-length
  ? 3 => uint,        ; est-ttft-ms for the queried capability, self-est.
  ? 4 => uint,        ; accepting: 0 no, 1 yes, 2 yes-if-reserved
  ? 5 => uint,        ; free vram-class right now
  ? 6 => bstr .size 8 ; echo (lets querier compute its own RTT — R3)
}

CapQuery    = { 1 => CapURI, ? 2 => uint /*shard*/, ? 3 => uint /*limit*/ }
CapResponse = {
  1 => [* bstr],      ; descriptor ENVELOPES (not bare CIDs) — the querier
                      ;  MUST verify each independently; the index is
                      ;  untrusted transport (§8)
  ? 2 => bool         ; more — the responder capped the batch (limit, ≤ 8)
}
